script:
frappe.ui.form.on('Gym Member', {
    // 1. Action buttons setup & Live Expiry Check
    refresh: function(frm) {
        if (frm.is_new()) return;

        // Form open hone par check kare agar date guzar gayi hai
        let today = frappe.datetime.get_today();
        if (frm.doc.membership_expiry_date && frm.doc.membership_expiry_date < today) {
            if (frm.doc.auto_renew && frm.doc.membership_status !== 'Frozen') {
                let new_expiry = frappe.datetime.add_months(frm.doc.membership_expiry_date, 1);
                frm.set_value('membership_expiry_date', new_expiry);
                frm.set_value('membership_status', 'Active');
                frm.save();
            } else if (!frm.doc.auto_renew && frm.doc.membership_status === 'Active') {
                frm.set_value('membership_status', 'Expired');
                frm.save();
            }
        }

        // Freeze Membership Button
        if (frm.doc.membership_status === 'Active') {
            frm.add_custom_button(__('Freeze Membership'), function() {
                frappe.prompt([
                    { fieldname: 'from_date', fieldtype: 'Date', label: 'Freeze From', reqd: 1, default: frappe.datetime.get_today() },
                    { fieldname: 'to_date', fieldtype: 'Date', label: 'Freeze To', reqd: 1 }
                ], function(values) {
                    frm.set_value('membership_status', 'Frozen');
                    frm.set_value('freeze_start_date', values.from_date);
                    frm.set_value('freeze_end_date', values.to_date);
                    frm.save();
                }, __('Hold / Freeze Membership'), __('Confirm Freeze'));
            }, __('Actions'));
        }

        // Resume Membership Button
        if (frm.doc.membership_status === 'Frozen') {
            frm.add_custom_button(__('Resume Membership'), function() {
                frm.set_value('membership_status', 'Active');
                frm.set_value('freeze_start_date', null);
                frm.set_value('freeze_end_date', null);
                frm.save();
            }, __('Actions'));
        }

        // Renew Membership Button (Creates Gym Invoice)
        frm.add_custom_button(__('Renew Membership'), function() {
            frappe.model.with_doc('Gym Plan', frm.doc.gym_plan, function() {
                let plan = frappe.get_doc('Gym Plan', frm.doc.gym_plan);
                let price = plan ? (plan.monthly_fee || plan.price || 0) : (frm.doc.monthly_fee || 0);

                frappe.new_doc('Gym Invoice', {
                    member: frm.doc.name,
                    posting_date: frappe.datetime.get_today(),
                    items: [{
                        item_description: (frm.doc.gym_plan || 'Membership') + ' - Renewal Fee',
                        qty: 1,
                        amount: price
                    }]
                });
            });
        }, __('Actions'));
    },

    // 2. Default values on new record
    onload: function(frm) {
        if (frm.is_new()) {
            if (!frm.doc.membership_status) frm.set_value('membership_status', 'Active');
            if (frm.doc.auto_renew === undefined) frm.set_value('auto_renew', 1);
            if (!frm.doc.joining_date) frm.set_value('joining_date', frappe.datetime.get_today());
        }
    },

    // 3. CNIC Auto-Formatter (XXXXX-XXXXXXX-X)
    cnic: function(frm) {
        if (!frm.doc.cnic) return;

        let raw = frm.doc.cnic.replace(/\D/g, '').substring(0, 13);
        let formatted = raw;

        if (raw.length > 12) {
            formatted = `${raw.substring(0, 5)}-${raw.substring(5, 12)}-${raw.substring(12, 13)}`;
        } else if (raw.length > 5) {
            formatted = `${raw.substring(0, 5)}-${raw.substring(5, 12)}`;
        }

        if (frm.doc.cnic !== formatted) {
            frm.set_value('cnic', formatted);
        }
    },

    // 4. Plan change calculations
    gym_plan: function(frm) {
        if (frm.doc.gym_plan) {
            frappe.db.get_doc('Gym Plan', frm.doc.gym_plan).then(plan => {
                if (plan.monthly_fee) {
                    frm.set_value('monthly_fee', plan.monthly_fee);
                } else if (plan.price) {
                    frm.set_value('monthly_fee', plan.price);
                }

                if (frm.doc.joining_date) {
                    let months = plan.duration_in_months || 1;
                    let expiry = frappe.datetime.add_months(frm.doc.joining_date, months);
                    frm.set_value('membership_expiry_date', expiry);
                }
            });
        }
    },

    // 5. Joining date change calculations
    joining_date: function(frm) {
        if (frm.doc.gym_plan && frm.doc.joining_date) {
            frm.trigger('gym_plan');
        }
    }
});

frappe.ui.form.on('Gym Invoice', {
    refresh: function(frm) {
        frm.toggle_display('payment_status', true);
        toggle_payment_fields(frm);

        if (frm.is_new()) {
            calculate_totals(frm, false);
        }

        // Submittable / Submitted Invoice par outstanding receive karne ka button
        if (frm.doc.docstatus === 1 && flt(frm.doc.outstanding_amount) > 0) {
            frm.add_custom_button(__('Receive Remaining (PKR ' + frm.doc.outstanding_amount + ')'), function() {
                frappe.prompt([
                    {
                        fieldname: 'received_amount',
                        fieldtype: 'Currency',
                        label: 'Amount Paying Now',
                        default: frm.doc.outstanding_amount,
                        reqd: 1
                    },
                    {
                        fieldname: 'payment_mode',
                        fieldtype: 'Select',
                        label: 'Payment Mode',
                        options: ['Cash', 'Bank Transfer', 'EasyPaisa', 'JazzCash'],
                        default: 'Cash',
                        reqd: 1
                    }
                ], function(values) {
                    let entered_amount = flt(values.received_amount);
                    if (entered_amount <= 0 || entered_amount > flt(frm.doc.outstanding_amount)) {
                        frappe.msgprint(__('Payment amount must be between 1 and outstanding balance.'));
                        return;
                    }

                    let new_paid = flt(frm.doc.amount_paid) + entered_amount;
                    let new_outstanding = Math.max(0, flt(frm.doc.total_amount) - new_paid);
                    let new_status = (new_outstanding === 0) ? 'Paid' : 'Partially Paid';

                    frappe.call({
                        method: 'frappe.client.set_value',
                        args: {
                            doctype: 'Gym Invoice',
                            name: frm.doc.name,
                            fieldname: {
                                amount_paid: new_paid,
                                outstanding_amount: new_outstanding,
                                payment_status: new_status,
                                payment_mode: values.payment_mode
                            }
                        },
                        callback: function() {
                            frm.reload_doc();
                            frappe.show_alert({
                                message: __('Payment recorded successfully!'),
                                indicator: 'green'
                            });
                        }
                    });
                }, __('Clear Outstanding Dues'), __('Confirm Payment'));
            }).addClass('btn-primary');
        }
    },

    onload: function(frm) {
        frm.toggle_display('payment_status', true);
    },

    // Member select hone par Plan, Fee aur Promo Code auto-validate
    member: function(frm) {
        if (!frm.doc.member) return;

        frappe.db.get_doc('Gym Member', frm.doc.member).then(member => {
            let plan_name = member.gym_plan || 'Monthly Membership';
            let fee = flt(member.monthly_fee);

            let set_item_row = function(amount) {
                if (!frm.doc.items || frm.doc.items.length === 0) {
                    let row = frm.add_child('items');
                    row.item_description = plan_name + ' - Monthly Fee';
                    row.qty = 1;
                    row.amount = amount;
                } else {
                    frm.doc.items[0].item_description = plan_name + ' - Monthly Fee';
                    frm.doc.items[0].qty = 1;
                    frm.doc.items[0].amount = amount;
                }
                frm.refresh_field('items');
                calculate_totals(frm, true);
            };

            // Agar Member par fee set nahi hai toh direct Gym Plan se price uthao
            if (fee > 0) {
                set_item_row(fee);
            } else if (member.gym_plan) {
                frappe.db.get_doc('Gym Plan', member.gym_plan).then(plan => {
                    let plan_fee = flt(plan.monthly_fee || plan.price || 0);
                    set_item_row(plan_fee);
                });
            } else {
                set_item_row(0);
            }
        });

        // Agar promo code pehle se select hai aur member baad mein change hua
        if (frm.doc.promo_code) {
            validate_and_apply_promo(frm);
        }
    },

    // Promo Code Selection Event
    promo_code: function(frm) {
        validate_and_apply_promo(frm);
    },

    // Discount (%) change hone par total recalculate
    discount_percentage: function(frm) {
        calculate_totals(frm, true);
    },

    payment_option: function(frm) {
        toggle_payment_fields(frm);
        calculate_totals(frm, true);
    },

    amount_paid: function(frm) {
        calculate_totals(frm, false);
    },

    validate: function(frm) {
        calculate_totals(frm, false);
    }
});

// Child table calculation events
frappe.ui.form.on('Gym Invoice Item', {
    amount: function(frm) { calculate_totals(frm, true); },
    qty: function(frm) { calculate_totals(frm, true); },
    items_remove: function(frm) { calculate_totals(frm, true); }
});

// --- Helper Functions ---

function toggle_payment_fields(frm) {
    let is_pay_now = (frm.doc.payment_option === 'Pay Now');
    frm.toggle_display(['payment_mode', 'amount_paid', 'reference__txn_id'], is_pay_now);
    frm.toggle_display('due_date', !is_pay_now);
}

function calculate_totals(frm, auto_fill_paid) {
    let items_sum = 0;
    (frm.doc.items || []).forEach(row => {
        items_sum += (flt(row.qty || 1) * flt(row.amount || 0));
    });

    // Percentage discount formula
    let discount_pct = flt(frm.doc.discount_percentage) || 0;
    let discount_val = (items_sum * discount_pct) / 100.0;
    let net_total = Math.max(0, items_sum - discount_val);

    frm.set_value('total_amount', net_total);

    if (frm.doc.payment_option === 'Pay Now') {
        if (auto_fill_paid || frm.doc.amount_paid === undefined || frm.doc.amount_paid === null) {
            frm.set_value('amount_paid', net_total);
        }

        let paid = flt(frm.doc.amount_paid);
        let outstanding = Math.max(0, net_total - paid);
        frm.set_value('outstanding_amount', outstanding);

        if (paid >= net_total && net_total > 0) {
            frm.set_value('payment_status', 'Paid');
        } else if (paid > 0 && paid < net_total) {
            frm.set_value('payment_status', 'Partially Paid');
        } else {
            frm.set_value('payment_status', 'Unpaid');
        }
    } else {
        frm.set_value('amount_paid', 0);
        frm.set_value('outstanding_amount', net_total);
        frm.set_value('payment_status', 'Unpaid');
    }

    frm.refresh_field('payment_status');
    frm.refresh_field('outstanding_amount');
    frm.refresh_field('total_amount');
}

// --- Promo Code Validation & Discount Engine ---

function validate_and_apply_promo(frm) {
    if (!frm.doc.promo_code) {
        frm.set_value('discount_percentage', 0);
        calculate_totals(frm, true);
        return;
    }

    if (!frm.doc.member) {
        frappe.msgprint(__('Please select a Member first before applying Promo Code.'));
        frm.set_value('promo_code', '');
        frm.set_value('discount_percentage', 0);
        calculate_totals(frm, true);
        return;
    }

    frappe.db.get_doc('Gym Promo Code', frm.doc.promo_code).then(promo => {
        let today = frappe.datetime.get_today();

        // 1. Is Active Check
        if (!promo.is_active) {
            frappe.msgprint(__('This Promo Code is currently inactive.'));
            reset_promo(frm);
            return;
        }

        // 2. Expiry Check
        if (promo.valid_till && promo.valid_till < today) {
            frappe.msgprint(__('This Promo Code has expired on ' + promo.valid_till + '.'));
            reset_promo(frm);
            return;
        }

        // 3. Single Use Per Member Check
        if (promo.single_use_per_member) {
            frappe.db.count('Gym Invoice', {
                filters: {
                    member: frm.doc.member,
                    promo_code: frm.doc.promo_code,
                    name: ['!=', frm.doc.name || '']
                }
            }).then(usage_count => {
                if (usage_count > 0) {
                    frappe.msgprint(__('This member has already used this Promo Code (One-Time Only).'));
                    reset_promo(frm);
                    return;
                }
                check_max_usage_and_apply(frm, promo);
            });
        } else {
            check_max_usage_and_apply(frm, promo);
        }
    });
}

function check_max_usage_and_apply(frm, promo) {
    if (promo.max_usage && promo.max_usage > 0) {
        frappe.db.count('Gym Invoice', {
            filters: {
                promo_code: frm.doc.promo_code,
                name: ['!=', frm.doc.name || '']
            }
        }).then(total_usage => {
            if (total_usage >= promo.max_usage) {
                frappe.msgprint(__('This Promo Code has reached its maximum overall usage limit.'));
                reset_promo(frm);
                return;
            }
            apply_promo_discount(frm, promo.discount_percentage);
        });
    } else {
        apply_promo_discount(frm, promo.discount_percentage);
    }
}

function reset_promo(frm) {
    frm.set_value('promo_code', '');
    frm.set_value('discount_percentage', 0);
    calculate_totals(frm, true);
}

function apply_promo_discount(frm, discount) {
    frm.set_value('discount_percentage', discount);
    calculate_totals(frm, true);
    frappe.show_alert({
        message: __('Promo Code Applied: ' + discount + '% Discount!'),
        indicator: 'green'
    });
}

