frappe.ui.form.on('Gym Invoice Item', {
    amount: function(frm) { calculate_totals(frm, true); },
    qty: function(frm) { calculate_totals(frm, true); },
    items_remove: function(frm) { calculate_totals(frm, true); }
});

function toggle_payment_fields(frm) {
    let is_pay_now = (frm.doc.payment_option === 'Pay Now');
    frm.toggle_display(['payment_mode', 'amount_paid', 'reference__txn_id'], is_pay_now);
    frm.toggle_display('due_date', !is_pay_now);
}

function calculate_totals(frm, auto_fill_paid) {
    let total = 0;
    (frm.doc.items || []).forEach(row => {
        total += ((row.qty || 1) * (row.amount || 0));
    });

    frm.set_value('total_amount', total);

    if (frm.doc.payment_option === 'Pay Now') {
        if (auto_fill_paid || frm.doc.amount_paid === undefined || frm.doc.amount_paid === null) {
            frm.set_value('amount_paid', total);
        }

        let paid = flt(frm.doc.amount_paid);
        let outstanding = Math.max(0, total - paid);
        
        frm.set_value('outstanding_amount', outstanding);

        if (paid >= total && total > 0) {
            frm.set_value('payment_status', 'Paid');
        } else if (paid > 0 && paid < total) {
            frm.set_value('payment_status', 'Partially Paid');
        } else {
            frm.set_value('payment_status', 'Unpaid');
        }
    } else {
        frm.set_value('amount_paid', 0);
        frm.set_value('outstanding_amount', total);
        frm.set_value('payment_status', 'Unpaid');
    }

    frm.refresh_field('payment_status');
    frm.refresh_field('outstanding_amount');
    frm.refresh_field('total_amount');
}

frappe.ui.form.on('Gym Payment Entry', {
    setup: function(frm) {
        // Invoice field par filter lagana
        frm.set_query('invoice', function() {
            if (!frm.doc.member) {
                frappe.msgprint(__('Pehle Member select karein.'));
                return {
                    filters: {
                        'docstatus': 1,
                        'payment_status': ['!=', 'Paid']
                    }
                };
            }
            return {
                filters: {
                    'member': frm.doc.member,
                    'docstatus': 1,
                    'payment_status': ['!=', 'Paid']
                }
            };
        });
    },

    member: function(frm) {
        // Jab member change ho toh purani invoice clear ho jaye aur latest unpaid invoice auto-fetch ho jaye
        frm.set_value('invoice', '');
        frm.set_value('amount_paid', 0);

        if (frm.doc.member) {
            frappe.db.get_list('Gym Invoice', {
                filters: {
                    member: frm.doc.member,
                    docstatus: 1,
                    payment_status: ['!=', 'Paid']
                },
                fields: ['name', 'outstanding_amount', 'total_amount'],
                order_by: 'creation desc',
                limit: 1
            }).then(records => {
                if (records && records.length > 0) {
                    frm.set_value('invoice', records[0].name);
                    frm.set_value('amount_paid', records[0].outstanding_amount || records[0].total_amount);
                }
            });
        }
    },

    invoice: function(frm) {
        if (frm.doc.invoice) {
            frappe.db.get_doc('Gym Invoice', frm.doc.invoice).then(inv => {
                if (inv.outstanding_amount) {
                    frm.set_value('amount_paid', inv.outstanding_amount);
                } else if (inv.total_amount) {
                    frm.set_value('amount_paid', inv.total_amount);
                }
            });
        }
    }
});

frappe.listview_settings['Gym Invoice'] = {
    add_fields: ["payment_status", "outstanding_amount"],
    get_indicator: function(doc) {
        if (doc.payment_status === "Paid") {
            return [__("Paid"), "green", "payment_status,=,Paid"];
        } else if (doc.payment_status === "Partially Paid") {
            return [__("Partially Paid"), "orange", "payment_status,=,Partially Paid"];
        } else {
            return [__("Unpaid"), "red", "payment_status,=,Unpaid"];
        }
    }
};

frappe.ui.form.on('Gym Payment Entry', {
    invoice: function(frm) {
        if (!frm.doc.invoice) return;
        
        frappe.db.get_doc('Gym Invoice', frm.doc.invoice).then(inv => {
            frm.set_value('member', inv.member);
            frm.set_value('amount_paid', inv.outstanding_amount || 0);
        });
    }
});

frappe.ui.form.on('Gym Quotation', {
    refresh: function(frm) {
        if (frm.is_new()) {
            if (!frm.doc.duration_months) {
                frm.set_value('duration_months', 1);
            }
            if (!frm.doc.quotation_date) {
                frm.set_value('quotation_date', frappe.datetime.get_today());
            }
            calculate_quote_total(frm);
        }

        // Quotation Accept hone par Gym Member ka form pre-filled open karega
        if (!frm.is_new() && frm.doc.status === 'Accepted') {
            frm.add_custom_button(__('Create Gym Member'), function() {
                frappe.new_doc('Gym Member', {
                    full_name: frm.doc.customer_name,
                    phone: frm.doc.phone,
                    gym_plan: frm.doc.gym_plan,
                    monthly_fee: frm.doc.monthly_fee,
                    joining_date: frappe.datetime.get_today(),
                    membership_status: 'Active'
                });
            }).addClass('btn-primary');
        }
    },

    gym_plan: function(frm) {
        if (!frm.doc.gym_plan) return;

        frappe.db.get_doc('Gym Plan', frm.doc.gym_plan).then(plan => {
            let fee = flt(plan.monthly_fee || plan.price || plan.fee || 0);
            frm.set_value('monthly_fee', fee);
            calculate_quote_total(frm);
        });
    },

    monthly_fee: function(frm) {
        calculate_quote_total(frm);
    },

    duration_months: function(frm) {
        calculate_quote_total(frm);
    },

    discount_percentage: function(frm) {
        calculate_quote_total(frm);
    }
});

function calculate_quote_total(frm) {
    let fee = flt(frm.doc.monthly_fee);
    let duration = flt(frm.doc.duration_months) || 1;
    let base_total = fee * duration;

    let discount_pct = flt(frm.doc.discount_percentage) || 0;
    let discount_val = (base_total * discount_pct) / 100.0;

    let final_total = Math.max(0, base_total - discount_val);

    frm.set_value('total_amount', final_total);
    frm.refresh_field('total_amount');
}

frappe.ui.form.on('Gym Attendance', {
    refresh: function(frm) {
        frm.set_df_property('member_name', 'read_only', 1);
        frm.set_df_property('gym_plan', 'read_only', 1);

        if (!frm.is_new() && !frm.doc.out_time) {
            frm.add_custom_button(__('Mark Check-out'), function() {
                frm.set_value('out_time', frappe.datetime.now_time());
                frm.save();
                frappe.show_alert({
                    message: __('Check-out time recorded!'),
                    indicator: 'green'
                });
            }).addClass('btn-primary');
        }
    },

    onload: function(frm) {
        if (frm.is_new()) {
            if (!frm.doc.attendance_date) {
                frm.set_value('attendance_date', frappe.datetime.get_today());
            }
            if (!frm.doc.in_time) {
                frm.set_value('in_time', frappe.datetime.now_time());
            }
            if (!frm.doc.status) {
                frm.set_value('status', 'Present');
            }
        }
    },

    member: function(frm) {
        if (!frm.doc.member) {
            reset_attendance_member(frm);
            return;
        }

        frappe.db.get_doc('Gym Member', frm.doc.member).then(member => {
            let status = member.membership_status || member.status || 'Active';
            let today = frappe.datetime.get_today();
            let is_expired = member.membership_expiry_date && (member.membership_expiry_date < today);

            // 1. Status Check
            if (status !== 'Active') {
                frappe.msgprint({
                    title: __('Access Denied'),
                    indicator: 'red',
                    message: __('Attendance cannot be marked! Member status is <b>' + status + '</b>.')
                });
                reset_attendance_member(frm);
                return;
            }

            // 2. Expiry Check
            if (is_expired) {
                frappe.msgprint({
                    title: __('Membership Expired'),
                    indicator: 'red',
                    message: __('Attendance cannot be marked! Membership expired on <b>' + member.membership_expiry_date + '</b>.')
                });
                reset_attendance_member(frm);
                return;
            }

            // 3. Invoice Dues Check (docstatus filter removed)
            frappe.db.get_list('Gym Invoice', {
                filters: {
                    member: frm.doc.member,
                    outstanding_amount: ['>', 0]
                },
                fields: ['name', 'outstanding_amount', 'due_date']
            }).then(invoices => {
                let resolved_name = member.full_name || 
                                    member.member_name || 
                                    ((member.first_name || '') + ' ' + (member.last_name || '')).trim() || 
                                    member.name;

                if (invoices && invoices.length > 0) {
                    // Check Overdue Invoices
                    let overdue_invoices = invoices.filter(inv => {
                        return inv.due_date && (inv.due_date < today);
                    });

                    if (overdue_invoices.length > 0) {
                        let overdue_amount = overdue_invoices.reduce((sum, inv) => sum + flt(inv.outstanding_amount), 0);
                        frappe.msgprint({
                            title: __('Overdue Payment - Access Blocked'),
                            indicator: 'red',
                            message: __('Attendance blocked! Due date has passed (' + overdue_invoices[0].due_date + '). Overdue amount: <b>PKR ' + overdue_amount.toLocaleString() + '</b>. Please clear dues.')
                        });
                        reset_attendance_member(frm);
                        return;
                    }

                    // Within Due Date (Allowed with Warning)
                    let pending_amount = invoices.reduce((sum, inv) => sum + flt(inv.outstanding_amount), 0);
                    let nearest_due = invoices[0].due_date || 'N/A';

                    frm.set_value('member_name', resolved_name);
                    frm.set_value('gym_plan', member.gym_plan || 'Standard');

                    frappe.show_alert({
                        message: __('Entry Allowed (Pending PKR ' + pending_amount.toLocaleString() + ' | Due: ' + nearest_due + ')'),
                        indicator: 'orange'
                    }, 7);
                    return;
                }

                // All clear
                frm.set_value('member_name', resolved_name);
                frm.set_value('gym_plan', member.gym_plan || 'Standard');

                frappe.show_alert({
                    message: __('Verified: ' + resolved_name + ' (All Dues Clear)'),
                    indicator: 'green'
                });
            });
        });
    },

    validate: function(frm) {
        if (!frm.doc.member) return;

        let today = frappe.datetime.get_today();

        return frappe.db.get_doc('Gym Member', frm.doc.member).then(member => {
            let status = member.membership_status || member.status || 'Active';
            let is_expired = member.membership_expiry_date && (member.membership_expiry_date < today);

            if (status !== 'Active') {
                frappe.throw(__('Cannot save attendance! Member is currently ' + status + '.'));
            }

            if (is_expired) {
                frappe.throw(__('Cannot save attendance! Membership expired on ' + member.membership_expiry_date + '.'));
            }

            return frappe.db.get_list('Gym Invoice', {
                filters: {
                    member: frm.doc.member,
                    outstanding_amount: ['>', 0]
                },
                fields: ['outstanding_amount', 'due_date']
            }).then(invoices => {
                if (invoices && invoices.length > 0) {
                    let overdue_invoices = invoices.filter(inv => inv.due_date && (inv.due_date < today));
                    if (overdue_invoices.length > 0) {
                        let overdue_amount = overdue_invoices.reduce((sum, inv) => sum + flt(inv.outstanding_amount), 0);
                        frappe.throw(__('Cannot save attendance! Member payment is overdue (PKR ' + overdue_amount.toLocaleString() + ').'));
                    }
                }
            });
        });
    }
});

function reset_attendance_member(frm) {
    frm.set_value('member', '');
    frm.set_value('member_name', '');
    frm.set_value('gym_plan', '');
}
